/* @autogenerated */
package net.civeira.phylax.integrationtest.feature.oauth.flow;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Base64;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.response.Response;
import net.civeira.phylax.integrationtest.feature.oauth.fixtures.OidcTestFixtures;

/**
 * Code exchange bound to client, tenant and redirect (0.1) and refresh bound to client, family and
 * session (0.2).
 */
@Tag("oidc-flow")
@QuarkusTest
class TokenGrantSecurityTest extends OidcIntegrationTestBase {

  private static final String VERIFIER = "dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk";

  private static String challenge(String verifier) throws Exception {
    byte[] digest =
        MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.US_ASCII));
    return Base64.getUrlEncoder().withoutPadding().encodeToString(digest);
  }

  private String codeWithoutPkce() {
    String code = client.extractAuthCode(client.submitLogin(OidcTestFixtures.TENANT,
        OidcTestFixtures.USERNAME, OidcTestFixtures.PASSWORD, null));
    Assertions.assertNotNull(code);
    return code;
  }

  private String passwordRefresh(String scope) {
    Response auth = client.passwordGrant(OidcTestFixtures.TENANT, OidcTestFixtures.CLIENT_ID,
        OidcTestFixtures.CLIENT_SECRET, OidcTestFixtures.USERNAME, OidcTestFixtures.PASSWORD,
        scope);
    Assertions.assertEquals(200, auth.statusCode());
    return auth.jsonPath().getString("refresh_token");
  }

  private static void assertError(Response response, int status, String error) {
    Assertions.assertEquals(status, response.statusCode());
    Assertions.assertEquals(error, response.jsonPath().getString("error"));
    Assertions.assertEquals("no-store", response.getHeader("Cache-Control"));
  }

  // ── 0.1 authorization code ────────────────────────────────────────────────

  @Test
  void code_withOtherRedirect_isRejected_withoutSpendingIt() {
    String code = codeWithoutPkce();

    assertError(client.exchangeCode(OidcTestFixtures.TENANT, code, "http://localhost/other",
        OidcTestFixtures.CLIENT_ID), 400, "invalid_grant");

    Assertions.assertEquals(200,
        client.exchangeCode(OidcTestFixtures.TENANT, code, OidcTestFixtures.REDIRECT_URI,
            OidcTestFixtures.CLIENT_ID).statusCode(),
        "A rejected request must not spend the code of the legitimate client");
  }

  @Test
  void code_withWrongSecret_isInvalidClient() {
    String code = codeWithoutPkce();

    assertError(
        client.exchangeCodeAsConfidential(OidcTestFixtures.TENANT, code,
            OidcTestFixtures.REDIRECT_URI, OidcTestFixtures.CLIENT_ID, "wrong-secret"),
        401, "invalid_client");
  }

  @Test
  void code_withOtherClient_isInvalidClient() {
    String code = codeWithoutPkce();

    assertError(
        client.exchangeCodeAsConfidential(OidcTestFixtures.TENANT, code,
            OidcTestFixtures.REDIRECT_URI, "other-client", OidcTestFixtures.CLIENT_SECRET),
        401, "invalid_client");
  }

  @Test
  void code_withoutPkce_byPublicClient_isRejected() {
    String code = codeWithoutPkce();

    assertError(
        client.exchangeCodeWithVerifier(OidcTestFixtures.TENANT, code,
            OidcTestFixtures.REDIRECT_URI, OidcTestFixtures.CLIENT_ID, VERIFIER),
        400, "invalid_grant");
  }

  @Test
  void code_withPkce_byPublicClient_isAccepted() throws Exception {
    String code = client.extractAuthCode(client.submitLoginWithPkce(OidcTestFixtures.TENANT,
        OidcTestFixtures.USERNAME, OidcTestFixtures.PASSWORD, null, challenge(VERIFIER), "S256"));

    Response exchange = client.exchangeCodeWithVerifier(OidcTestFixtures.TENANT, code,
        OidcTestFixtures.REDIRECT_URI, OidcTestFixtures.CLIENT_ID, VERIFIER);

    Assertions.assertEquals(200, exchange.statusCode());
    Assertions.assertEquals("no-store", exchange.getHeader("Cache-Control"));
  }

  @Test
  void code_onOtherTenant_isRejected() {
    String code = codeWithoutPkce();

    Response exchange = client.exchangeCode("other-tenant", code, OidcTestFixtures.REDIRECT_URI,
        OidcTestFixtures.CLIENT_ID);

    Assertions.assertNotEquals(200, exchange.statusCode());
    Assertions.assertEquals(200, client.exchangeCode(OidcTestFixtures.TENANT, code,
        OidcTestFixtures.REDIRECT_URI, OidcTestFixtures.CLIENT_ID).statusCode());
  }

  // ── 0.2 refresh token ─────────────────────────────────────────────────────

  @Test
  void refresh_rotates_andCarriesFamily() {
    String refresh = passwordRefresh("openid profile");

    Response rotated = client.refreshToken(OidcTestFixtures.TENANT, refresh,
        OidcTestFixtures.CLIENT_ID, OidcTestFixtures.CLIENT_SECRET);

    Assertions.assertEquals(200, rotated.statusCode());
    Map<String, Object> first = decodeToken(refresh);
    Map<String, Object> second = decodeToken(rotated.jsonPath().getString("refresh_token"));
    Assertions.assertEquals(first.get("fid"), second.get("fid"), "Rotation keeps the family");
    Assertions.assertEquals(first.get("fexp"), second.get("fexp"),
        "Rotation never extends the family");
  }

  @Test
  void refresh_reused_revokesTheFamily() {
    String refresh = passwordRefresh("openid profile");
    String rotated =
        client.refreshToken(OidcTestFixtures.TENANT, refresh, OidcTestFixtures.CLIENT_ID,
            OidcTestFixtures.CLIENT_SECRET).jsonPath().getString("refresh_token");

    assertError(client.refreshToken(OidcTestFixtures.TENANT, refresh, OidcTestFixtures.CLIENT_ID,
        OidcTestFixtures.CLIENT_SECRET), 400, "invalid_grant");

    assertError(client.refreshToken(OidcTestFixtures.TENANT, rotated, OidcTestFixtures.CLIENT_ID,
        OidcTestFixtures.CLIENT_SECRET), 400, "invalid_grant");
  }

  @Test
  void refresh_cannotWidenScope_butCanNarrowIt() {
    String refresh = passwordRefresh("openid profile");

    assertError(client.refreshTokenWithScope(OidcTestFixtures.TENANT, refresh,
        OidcTestFixtures.CLIENT_ID, OidcTestFixtures.CLIENT_SECRET, "openid profile email"), 400,
        "invalid_scope");

    Response narrowed = client.refreshTokenWithScope(OidcTestFixtures.TENANT, refresh,
        OidcTestFixtures.CLIENT_ID, OidcTestFixtures.CLIENT_SECRET, "openid");
    Assertions.assertEquals(200, narrowed.statusCode());
    Assertions.assertEquals(List.of("openid"),
        claimAsList(decodeToken(narrowed.jsonPath().getString("access_token")).get("scope")));
  }

  @Test
  void refresh_withoutClientAuthentication_isInvalidClient() {
    String refresh = passwordRefresh("openid");

    assertError(client.refreshTokenWithoutClient(OidcTestFixtures.TENANT, refresh), 401,
        "invalid_client");
  }

  @Test
  void refresh_withWrongSecret_isInvalidClient_andDoesNotSpendIt() {
    String refresh = passwordRefresh("openid");

    assertError(client.refreshToken(OidcTestFixtures.TENANT, refresh, OidcTestFixtures.CLIENT_ID,
        "wrong-secret"), 401, "invalid_client");

    Assertions.assertEquals(200, client.refreshToken(OidcTestFixtures.TENANT, refresh,
        OidcTestFixtures.CLIENT_ID, OidcTestFixtures.CLIENT_SECRET).statusCode());
  }

  @Test
  void refresh_ofInteractiveSession_stopsAfterLogout() {
    Response exchange = client.exchangeCode(OidcTestFixtures.TENANT, codeWithoutPkce(),
        OidcTestFixtures.REDIRECT_URI, OidcTestFixtures.CLIENT_ID);
    String refresh = exchange.jsonPath().getString("refresh_token");
    Assertions.assertEquals(Boolean.TRUE, decodeToken(refresh).get("ses"));
    String rotated =
        client.refreshToken(OidcTestFixtures.TENANT, refresh, OidcTestFixtures.CLIENT_ID,
            OidcTestFixtures.CLIENT_SECRET).jsonPath().getString("refresh_token");
    Assertions.assertNotNull(rotated, "The refresh works while the session is alive");

    sessionStore.clear();

    assertError(client.refreshToken(OidcTestFixtures.TENANT, rotated, OidcTestFixtures.CLIENT_ID,
        OidcTestFixtures.CLIENT_SECRET), 400, "invalid_grant");
  }
}
